package com.marketplace;
import java.util.*;import java.math.*;import org.springframework.stereotype.*;import org.springframework.transaction.annotation.Transactional;import org.springframework.scheduling.annotation.Scheduled;
@Service public class Commerce {
 final Db d;Commerce(Db d){this.d=d;}
 public record Checkout(long addressId,String shipping,String coupon,String mode){}
 BigDecimal decimal(Map<String,Object>m,String k){return (BigDecimal)m.get(k);}
 void notify(long user,String text){d.exec("insert into outbox(user_id,message) values(?,?)",user,text);}
 BigDecimal coupon(long uid,String code,BigDecimal subtotal,boolean lock){if(code==null||code.isBlank())return BigDecimal.ZERO;var p=d.one("select * from promotions where code=?"+(lock?" for update":""),code.toUpperCase(Locale.ROOT));var valid=d.id("select count(*) from promotions where code=? and starts<=now() and ends>now() and used<usage_limit",code.toUpperCase(Locale.ROOT));if(valid==0||subtotal.compareTo(decimal(p,"minimum"))<0||d.id("select count(*) from redemptions where user_id=? and code=?",uid,code.toUpperCase(Locale.ROOT))>=Db.n(p,"per_user"))throw new Failure(409,"COUPON_INELIGIBLE","Coupon is expired, exhausted, previously used, or below minimum");BigDecimal amount=decimal(p,"amount");return Pricing.money(("PERCENT".equals(p.get("kind"))?subtotal.multiply(amount).divide(new BigDecimal("100")):amount).min(decimal(p,"max_discount")).min(subtotal));}
 List<Map<String,Object>> items(long uid,boolean lock){return d.all("select ci.quantity,v.*,p.id product_id,p.title,p.image,p.seller_id,s.name seller_name from cart_items ci join variants v on v.id=ci.variant_id join products p on p.id=v.product_id join stores s on s.id=p.seller_id where ci.user_id=? and p.active and s.active order by v.id"+(lock?" for update of v":""),uid);}
 BigDecimal subtotal(List<Map<String,Object>> rows){return rows.stream().map(i->decimal(i,"price").multiply(BigDecimal.valueOf(Db.n(i,"quantity")))).reduce(BigDecimal.ZERO,BigDecimal::add);}
 @Transactional public Pricing.Totals quote(long uid,Checkout b){var rows=items(uid,false);if(rows.isEmpty())throw new Failure(409,"EMPTY_CART","Your cart is empty");BigDecimal sub=subtotal(rows);return Pricing.calculate(sub,coupon(uid,b.coupon(),sub,false),b.shipping());}
 @Transactional public Map<String,Object> checkout(long uid,String key,Checkout b){Catalog.check(key,8,100);if(!List.of("success","decline","delay","timeout").contains(b.mode()))throw new IllegalArgumentException();
 // Customer lock serializes cart, idempotency, and per-customer promotion usage.
 d.one("select id from users where id=? for update",uid);var replay=d.all("select * from orders where user_id=? and idempotency_key=?",uid,key);if(!replay.isEmpty())return replay.get(0);
 var address=d.one("select * from addresses where id=? and user_id=?",b.addressId(),uid);var rows=items(uid,true);if(rows.isEmpty())throw new Failure(409,"EMPTY_CART","Your cart is empty");if(rows.size()!=d.id("select count(*) from cart_items where user_id=?",uid))throw new Failure(409,"UNAVAILABLE","A listing is unavailable; remove it from the cart");
 BigDecimal sub=subtotal(rows);BigDecimal dis=coupon(uid,b.coupon(),sub,true);var t=Pricing.calculate(sub,dis,b.shipping());String code=b.coupon()==null||b.coupon().isBlank()?null:b.coupon().toUpperCase(Locale.ROOT);
 String addr;try{addr=new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(address);}catch(Exception ex){throw new IllegalArgumentException();}
 long oid=d.id("insert into orders(user_id,idempotency_key,subtotal,discount,tax,shipping,total,coupon,address) values(?,?,?,?,?,?,?,?,?::jsonb) returning id",uid,key,t.subtotal(),t.discount(),t.tax(),t.shipping(),t.total(),code,addr);
 var weights=rows.stream().map(i->decimal(i,"price").multiply(BigDecimal.valueOf(Db.n(i,"quantity")))).toList();var ds=Pricing.allocate(t.discount(),weights);var ts=Pricing.allocate(t.tax(),weights);var ss=Pricing.allocate(t.shipping(),weights);
 for(int ix=0;ix<rows.size();ix++){var i=rows.get(ix);long vid=Db.n(i,"id"),qty=Db.n(i,"quantity");if(d.exec("update variants set reserved=reserved+? where id=? and stock-reserved>=?",qty,vid,qty)!=1)throw new Failure(409,"OUT_OF_STOCK",Db.str(i,"title")+" does not have enough stock");d.exec("insert into reservations(order_id,variant_id,quantity) values(?,?,?)",oid,vid,qty);d.exec("insert into inventory_ledger(variant_id,order_id,delta,reason) values(?,?,0,'RESERVED')",vid,oid);long so=d.id("insert into seller_orders(order_id,seller_id) values(?,?) on conflict(order_id,seller_id) do update set seller_id=excluded.seller_id returning id",oid,i.get("seller_id"));d.exec("insert into order_items(order_id,seller_order_id,variant_id,product_id,title,sku,color,seller_name,image,quantity,unit_price,discount,tax,shipping) values(?,?,?,?,?,?,?,?,?,?,?,?,?,?)",oid,so,vid,i.get("product_id"),i.get("title"),i.get("sku"),i.get("color"),i.get("seller_name"),i.get("image"),qty,i.get("price"),ds.get(ix),ts.get(ix),ss.get(ix));}
 if(code!=null){d.exec("update promotions set used=used+1 where code=?",code);d.exec("insert into redemptions values(?,?,?)",oid,uid,code);}d.exec("delete from cart_items where user_id=?",uid);
 if(b.mode().equals("success")||b.mode().equals("decline"))settle(oid,"initial-"+oid,b.mode().equals("success")?"success":"failed");else if(b.mode().equals("delay"))d.exec("update orders set expires_at=now()+interval '10 minutes' where id=?",oid);
 notify(uid,"Order #"+oid+" created. Demo payment: "+b.mode());return d.one("select * from orders where id=?",oid);}
 @Transactional public Map<String,Object> settle(long oid,String event,String outcome){Catalog.check(event,4,100);if(!List.of("success","failed").contains(outcome))throw new IllegalArgumentException();var o=d.one("select * from orders where id=? for update",oid);if(d.exec("insert into payment_events(event_id,order_id,outcome) values(?,?,?) on conflict do nothing",event,oid,outcome)==0)return o;String state=Db.str(o,"payment_state");if(state.equals("PAID")||state.equals("REFUNDED")||state.equals("REFUND_REQUIRED"))return o;
 boolean expired=d.id("select count(*) from orders where id=? and expires_at<=now()",oid)>0;
 if(state.equals("PENDING")&&!expired){if(outcome.equals("success")){for(var r:d.all("select * from reservations where order_id=? and state='HELD' order by variant_id for update",oid)){d.exec("update variants set stock=stock-?,reserved=reserved-? where id=?",r.get("quantity"),r.get("quantity"),r.get("variant_id"));d.exec("insert into inventory_ledger(variant_id,order_id,delta,reason) values(?,?,?,'SOLD')",r.get("variant_id"),oid,-Db.n(r,"quantity"));}for(var low:d.all("select st.user_id,p.title,v.stock-v.reserved available from reservations r join variants v on v.id=r.variant_id join products p on p.id=v.product_id join stores st on st.id=p.seller_id where r.order_id=? and v.stock-v.reserved<=v.threshold",oid))notify(Db.n(low,"user_id"),"Low stock: "+low.get("title")+" — "+low.get("available")+" available");d.exec("update reservations set state='COMMITTED' where order_id=?",oid);d.exec("update orders set payment_state='PAID' where id=?",oid);notify(Db.n(o,"user_id"),"Payment received for order #"+oid);for(var s:d.all("select st.user_id from seller_orders so join stores st on st.id=so.seller_id where so.order_id=?",oid))notify(Db.n(s,"user_id"),"New paid order #"+oid);}else release(o,"FAILED");}
 else {if(state.equals("PENDING"))release(o,"EXPIRED");if(outcome.equals("success")){d.exec("update orders set payment_state='REFUND_REQUIRED' where id=?",oid);notify(Db.n(o,"user_id"),"Late payment for #"+oid+": refund required; no stock deducted. Contact admin.");}}
 return d.one("select * from orders where id=?",oid);}
 void release(Map<String,Object> o,String state){long oid=Db.n(o,"id");for(var r:d.all("select * from reservations where order_id=? and state='HELD' order by variant_id for update",oid)){d.exec("update variants set reserved=reserved-? where id=?",r.get("quantity"),r.get("variant_id"));d.exec("insert into inventory_ledger(variant_id,order_id,delta,reason) values(?,?,0,?)",r.get("variant_id"),oid,"RELEASED_"+state);}d.exec("update reservations set state='RELEASED' where order_id=? and state='HELD'",oid);d.exec("update orders set payment_state=? where id=?",state,oid);var red=d.all("delete from redemptions where order_id=? returning code",oid);if(!red.isEmpty())d.exec("update promotions set used=used-1 where code=?",red.get(0).get("code"));notify(Db.n(o,"user_id"),"Order #"+oid+" payment "+state.toLowerCase()+". Reservation released.");}
 @Transactional public Object cancel(long uid,long oid){var o=d.one("select * from orders where id=? and user_id=? for update",oid,uid);String state=Db.str(o,"payment_state");if(state.equals("CANCELLED")||state.equals("REFUNDED"))return o;if(!List.of("PENDING","PAID").contains(state))throw new Failure(409,"INVALID_STATE","This order cannot be cancelled");if(d.id("select count(*) from seller_orders where order_id=? and fulfillment<>'PROCESSING'",oid)>0)throw new Failure(409,"ALREADY_FULFILLED","A seller has started fulfillment; request a return after delivery");if(state.equals("PENDING"))release(o,"CANCELLED");else {for(var so:d.all("select id from seller_orders where order_id=? order by id",oid))refund(Db.n(so,"id"),false);d.exec("update orders set payment_state='REFUNDED' where id=?",oid);}d.exec("update seller_orders set fulfillment='CANCELLED' where order_id=?",oid);return d.one("select * from orders where id=?",oid);}
 void refund(long so,boolean returned){var s=d.one("select * from seller_orders where id=?",so);long oid=Db.n(s,"order_id");BigDecimal amount=(BigDecimal)d.one("select sum(unit_price*quantity-discount+tax+shipping) amount from order_items where seller_order_id=?",so).get("amount");if(d.exec("insert into refunds(order_id,seller_order_id,amount) values(?,?,?) on conflict(seller_order_id) do nothing",oid,so,amount)==0)return;for(var i:d.all("select * from order_items where seller_order_id=? order by variant_id",so)){d.exec("update variants set stock=stock+? where id=?",i.get("quantity"),i.get("variant_id"));d.exec("insert into inventory_ledger(variant_id,order_id,delta,reason) values(?,?,?,'REFUND_RESTOCK')",i.get("variant_id"),oid,i.get("quantity"));}d.exec("update seller_orders set fulfillment=? where id=?",returned?"RETURNED":"CANCELLED",so);if(d.id("select count(*) from seller_orders where order_id=? and fulfillment not in ('RETURNED','CANCELLED')",oid)==0)d.exec("update orders set payment_state='REFUNDED' where id=?",oid);notify(d.id("select user_id from orders where id=?",oid),"Demo refund completed for seller portion #"+so);}
 @Scheduled(fixedDelay=15000) @Transactional public void expire(){for(var o:d.all("select * from orders where payment_state='PENDING' and expires_at<=now() order by id for update skip locked limit 100"))release(o,"EXPIRED");}
 @Scheduled(fixedDelay=2000) @Transactional public void outbox(){for(var e:d.all("select * from outbox where not processed and attempts<5 order by id for update skip locked limit 50")){var tx=org.springframework.transaction.interceptor.TransactionAspectSupport.currentTransactionStatus();Object savepoint=tx.createSavepoint();try{d.exec("insert into notifications(outbox_id,user_id,message) values(?,?,?) on conflict(outbox_id) do nothing",e.get("id"),e.get("user_id"),e.get("message"));d.exec("update outbox set processed=true,attempts=attempts+1 where id=?",e.get("id"));tx.releaseSavepoint(savepoint);}catch(Exception ex){tx.rollbackToSavepoint(savepoint);tx.releaseSavepoint(savepoint);d.exec("update outbox set attempts=attempts+1,error='Notification delivery failed' where id=?",e.get("id"));}}}
}
